def ppo_update_entropy(
    logits, batch, lr=0.05, c=0.2, entropy_coef=0.01, epochs=4
) -> dict:
    """PPO 裁剪目标叠加熵正则的多轮 logits 更新，返回固定键序 logits、
    objectives、entropies、probabilities 的 dict。

